CREATE DATABASE IF NOT EXISTS bd_ladrillos_lark CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bd_ladrillos_lark;
-- Importar UNA VEZ en una base vacía. No elimina datos existentes.
CREATE TABLE rol(id INT PRIMARY KEY, nombre VARCHAR(30) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE usuario(id INT AUTO_INCREMENT PRIMARY KEY, rol_id INT NOT NULL, nombres VARCHAR(80) NOT NULL, apellidos VARCHAR(80) NOT NULL, dni CHAR(8) NOT NULL UNIQUE, correo VARCHAR(120) NOT NULL UNIQUE, telefono VARCHAR(20) NOT NULL, direccion VARCHAR(250) NOT NULL, usuario VARCHAR(50) NOT NULL UNIQUE, clave VARCHAR(300) NOT NULL, activo BOOLEAN NOT NULL DEFAULT 1, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(rol_id) REFERENCES rol(id)) ENGINE=InnoDB;
CREATE TABLE categoria(id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(80) NOT NULL UNIQUE, activo BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE producto(id INT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(100) NOT NULL, descripcion VARCHAR(1000) NOT NULL, categoria_id INT NOT NULL, precio DECIMAL(12,2) NOT NULL CHECK(precio>0), stock_minimo INT NOT NULL DEFAULT 10 CHECK(stock_minimo>=0), imagen VARCHAR(100) NOT NULL DEFAULT 'ladrillo.svg', activo BOOLEAN NOT NULL DEFAULT 1, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(categoria_id) REFERENCES categoria(id), INDEX(nombre)) ENGINE=InnoDB;
CREATE TABLE proveedor(id INT AUTO_INCREMENT PRIMARY KEY, ruc CHAR(11) NOT NULL UNIQUE, razon_social VARCHAR(150) NOT NULL, telefono VARCHAR(20) NOT NULL, correo VARCHAR(120) NOT NULL, direccion VARCHAR(250) NOT NULL, activo BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE producto_proveedor(producto_id INT NOT NULL, proveedor_id INT NOT NULL, PRIMARY KEY(producto_id,proveedor_id), FOREIGN KEY(producto_id) REFERENCES producto(id), FOREIGN KEY(proveedor_id) REFERENCES proveedor(id)) ENGINE=InnoDB;
CREATE TABLE inventario(producto_id INT PRIMARY KEY, stock INT NOT NULL DEFAULT 0 CHECK(stock>=0), FOREIGN KEY(producto_id) REFERENCES producto(id)) ENGINE=InnoDB;
CREATE TABLE venta(id INT AUTO_INCREMENT PRIMARY KEY, usuario_id INT NOT NULL, canal ENUM('PRESENCIAL') NOT NULL, subtotal DECIMAL(12,2) NOT NULL, descuento DECIMAL(12,2) NOT NULL DEFAULT 0, costo_delivery DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL, metodo VARCHAR(25) NOT NULL, estado VARCHAR(25) NOT NULL DEFAULT 'PENDIENTE', token CHAR(36) NOT NULL UNIQUE, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(usuario_id) REFERENCES usuario(id), INDEX(fecha)) ENGINE=InnoDB;
CREATE TABLE detalle_venta(id INT AUTO_INCREMENT PRIMARY KEY, venta_id INT NOT NULL, producto_id INT NOT NULL, cantidad INT NOT NULL CHECK(cantidad>0), precio DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, FOREIGN KEY(venta_id) REFERENCES venta(id), FOREIGN KEY(producto_id) REFERENCES producto(id), UNIQUE(venta_id,producto_id)) ENGINE=InnoDB;
CREATE TABLE pedido(id INT AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(50) NOT NULL UNIQUE, venta_id INT NOT NULL UNIQUE, direccion VARCHAR(250) NOT NULL, total DECIMAL(12,2) NOT NULL, metodo VARCHAR(25) NOT NULL, estado VARCHAR(25) NOT NULL DEFAULT 'PENDIENTE', fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(venta_id) REFERENCES venta(id), INDEX(fecha), INDEX(estado)) ENGINE=InnoDB;
CREATE TABLE detalle_pedido(id INT AUTO_INCREMENT PRIMARY KEY, pedido_id INT NOT NULL, producto_id INT NOT NULL, cantidad INT NOT NULL CHECK(cantidad>0), precio DECIMAL(12,2) NOT NULL, FOREIGN KEY(pedido_id) REFERENCES pedido(id), FOREIGN KEY(producto_id) REFERENCES producto(id)) ENGINE=InnoDB;
CREATE TABLE pago(id INT AUTO_INCREMENT PRIMARY KEY, venta_id INT NOT NULL UNIQUE, metodo VARCHAR(25) NOT NULL, importe DECIMAL(12,2) NOT NULL, estado VARCHAR(25) NOT NULL DEFAULT 'PENDIENTE', referencia VARCHAR(100) NOT NULL DEFAULT 'SIMULACION', fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(venta_id) REFERENCES venta(id)) ENGINE=InnoDB;
CREATE TABLE delivery(id INT AUTO_INCREMENT PRIMARY KEY, pedido_id INT NOT NULL UNIQUE, direccion VARCHAR(250) NOT NULL, distrito VARCHAR(100) NOT NULL, referencia VARCHAR(250) NOT NULL, telefono VARCHAR(20) NOT NULL, costo DECIMAL(12,2) NOT NULL, fecha_estimada DATE NOT NULL, fecha_entrega DATETIME NULL, estado VARCHAR(25) NOT NULL DEFAULT 'PENDIENTE', FOREIGN KEY(pedido_id) REFERENCES pedido(id)) ENGINE=InnoDB;
CREATE TABLE movimiento_inventario(id INT AUTO_INCREMENT PRIMARY KEY, producto_id INT NOT NULL, usuario_id INT NOT NULL, proveedor_id INT NULL, venta_id INT NULL, tipo VARCHAR(25) NOT NULL, cantidad INT NOT NULL, stock_resultante INT NOT NULL CHECK(stock_resultante>=0), motivo VARCHAR(250) NOT NULL, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(producto_id) REFERENCES producto(id), FOREIGN KEY(usuario_id) REFERENCES usuario(id), FOREIGN KEY(proveedor_id) REFERENCES proveedor(id), FOREIGN KEY(venta_id) REFERENCES venta(id), INDEX(producto_id,fecha)) ENGINE=InnoDB;
